        /// <inheritdoc />
        protected override void Down(MigrationBuilder migrationBuilder)
        {
            migrationBuilder.Sql("""
                DELETE FROM route_requests
                WHERE from_facility_id IN (
                    SELECT id FROM facilities WHERE code LIKE 'OSM_HOSPITAL_%'
                );
                """);

            migrationBuilder.Sql("DELETE FROM facilities WHERE code LIKE 'OSM_HOSPITAL_%';");
        }

        private static void InsertFacility(
            MigrationBuilder migrationBuilder,
            string name,
            string code,
            double longitude,
            double latitude,
            string boundary)
        {
            var boundarySql = boundary is null
                ? "NULL"
                : $"ST_SetSRID(ST_GeomFromGeoJSON('{EscapeSql(boundary)}'), 4326)";

            migrationBuilder.Sql($"""
                INSERT INTO facilities (name, code, facility_type, location, boundary)
                VALUES (
                    '{EscapeSql(name)}',
                    '{code}',
                    'HOSPITAL',
                    ST_SetSRID(ST_MakePoint({Format(longitude)}, {Format(latitude)}), 4326),
                    {boundarySql}
                )
                ON CONFLICT (code) DO NOTHING;
                """);
        }

        private static string EscapeSql(string value) => value.Replace("'", "''");

        private static string Format(double value) =>
            value.ToString("0.#######", CultureInfo.InvariantCulture);
    }
